using CouponBook.Api.Dtos;using CouponBook.Business.Auth;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.RateLimiting;
namespace CouponBook.Api.Controllers;
[ApiController][Route("api/auth")][EnableRateLimiting("auth")]public class AuthController:ControllerBase{private readonly IAccountService _a;private readonly IWebHostEnvironment _env;public AuthController(IAccountService a,IWebHostEnvironment env){_a=a;_env=env;}[HttpPost("otp/request")]public async Task<IActionResult> RequestOtp(RequestOtpRequest r){var x=await _a.RequestOtpAsync(r.Mobile);if(!x.Succeeded)return BadRequest(new{code=x.ErrorCode,errors=x.Errors});return Ok(new{status=x.Value!.Status,developmentCode=_env.IsDevelopment()?x.Value.DevelopmentCode:null});}[HttpPost("otp/verify")]public async Task<IActionResult> Verify(VerifyOtpRequest r){var x=await _a.VerifyOtpAsync(r.Mobile,r.Code,r.FullName);return x.Succeeded?Ok(x.Value):Unauthorized(new{code=x.ErrorCode,errors=x.Errors});}}
